INSERT INTO Afectiuni (nume_afectiune, descriere_generala) VALUES
('Diabet Zaharat Tip 2', 'Afecțiune metabolică cronică caracterizată prin niveluri ridicate de glucoză în sânge (hiperglicemie) cauzată de rezistența celulelor la insulină și deficitul relativ de insulină.'),
('Hipertensiune Arterială', 'Afecțiune cardiovasculară cronică caracterizată prin creșterea permanentă a presiunii sângelui în artere peste valorile normale (140/90 mmHg).'),
('Hipercolesteromie', 'Tulburare metabolică definită prin prezența unei cantități crescute de colesterol în sânge, un factor de risc major pentru dezvoltarea bolilor cardiovasculare.'),
('Steatoză Hepatică', 'Cunoscută și sub numele de ficat gras, reprezintă acumularea excesivă de grăsimi (trigliceride) în celulele hepatice, adesea asociată cu obezitatea și sindromul metabolic.'),
('Anemie Feriprivă', 'Cel mai frecvent tip de anomalie hematologică, caracterizată prin scăderea numărului de globule roșii și a hemoglobinei din cauza lipsei de fier din organism.'),
('Astm Bronșic', 'Boală cronică a căilor respiratorii caracterizată prin inflamație și îngustarea reversibilă a bronhiilor, manifestată prin episoade recurente de wheezing, dispnee și tuse.');
